import{Z as t,e as o,f as a,a0 as n}from"./chunks/framework.DmpHOl9T.js";const g=JSON.parse('{"title":"Web Request","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/automations/web-request.md","filePath":"integrations/automations/web-request.md","lastUpdated":1780377007000}'),i={name:"integrations/automations/web-request.md"};function s(r,e,l,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="web-request" tabindex="-1">Web Request <a class="header-anchor" href="#web-request" aria-label="Permalink to &quot;Web Request&quot;">​</a></h1><p>A general-purpose web request that can be used to send any URL you provide with the payload of content. This can be used to POST-forward content to a URL you choose.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Automations</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>Web Request</strong> as the <strong>Integration Provider</strong>.</li><li>Save the integration.</li></ol><h3 id="step-2-form-setting-test-payload" tabindex="-1">Step 2. Form Setting &amp; Test Payload <a class="header-anchor" href="#step-2-form-setting-test-payload" aria-label="Permalink to &quot;Step 2. Form Setting &amp; Test Payload&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration. Choose the destination workflow or URL supported by this integration and map the submitted values it needs. Use a test destination while checking the connection.</li><li>Click <strong>Save</strong> to save the form.</li><li>Click on the <strong>Send Test Payload</strong> button to send dummy content to the URL.</li></ol><h2 id="verify-a-submission" tabindex="-1">Verify a Submission <a class="header-anchor" href="#verify-a-submission" aria-label="Permalink to &quot;Verify a Submission&quot;">​</a></h2><p>Save the form, open it on your site and submit recognisable test values. Inspect the receiving workflow’s run history or request log. Check both the received values and the outcome of any following steps.</p><p>If nothing arrives, check whether integration conditions matched, whether the submission was complete and non-spam, and whether Craft’s queue has processed the job. A successful connection check verifies credentials; it does not prove that field mapping and delivery work. See <a href="/integrations/connect-and-test-an-integration">Connect and Test an Integration</a> for a complete mapping and verification workflow.</p>',9)])])}const p=t(i,[["render",s]]);export{g as __pageData,p as default};
